 currentTool(){if(LiveCanvas.isTyping())return 'text';if(drag?.type==='wireCut'||document.body.classList.contains('wire-cut-mode'))return 'cut';if(boardConnect||scheduleConnect)return 'wire';if(spacePressed||drag?.type==='node'||drag?.type==='pan')return 'hand';return tool},
