 publishPresence(force=false){if(!this.channel||!this.realtimeReady)return;const presence={name:this.name().slice(0,40),user_id:this.user,tool:this.currentTool(),view:tab},signature=JSON.stringify(presence);if(!force&&signature===this.lastPresence)return;this.lastPresence=signature;return this.channel.track(presence).catch(()=>{this.lastPresence=null})},
