 onlinePeople(){if(!this.channel)return [];const now=Date.now();for(const [id,person] of this.people)if(person.missingSince&&now-person.missingSince>10000&&now-(this.peers.get(id)?.seen||0)>10000){this.people.delete(id);this.peers.delete(id)}return [...this.people.values()]},
