 async pull(){if(!this.room||this.pulling)return;this.pulling=true;const room=this.room,generation=this.generation;try{const query='/rest/v1/canvas_rooms?id=eq.'+encodeURIComponent(room),heads=await sb(query+'&select=id,revision',{},true);if(generation!==this.generation)return;if(!heads?.length){this.channel?.unsubscribe();this.client?.realtime.disconnect();this.channel=null;throw Error('Shared canvas not available. Ask the owner for access.')}if(Number(heads[0].revision)>this.revision||!this.canonical){const rows=await sb(query+'&select=*',{},true);if(generation!==this.generation||!rows?.length)return;const row=rows[0];this.changed();if(Number(row.revision)>=this.revision){this.canonical=row.payload;this.revision=Number(row.revision);this.project()}}this.status=this.realtimeReady?'Live':'Syncing';this.lastError=null}catch(e){if(generation===this.generation)this.problem(e)}finally{this.pulling=false}},
