 sendPointer(point){this.lastPoint=point;if(!this.channel)return;this.publishPresence();const live=LiveCanvas.sample();this.channel.send({type:'broadcast',event:'cursor',payload:{peer:this.user,name:this.name().slice(0,40),boardId:board().id,tool:this.currentTool(),view:tab,point,moving:[],live}})},
