   const tx=p.point.x*zoom+pan.x,ty=p.point.y*zoom+pan.y,t=performance.now();if(cursor._tx!==tx||cursor._ty!==ty){cursor._fromX=cursor._x??tx;cursor._fromY=cursor._y??ty;cursor._tx=tx;cursor._ty=ty;cursor._at=t}const f=Math.min(1,(t-cursor._at)/40);cursor._x=cursor._fromX+(tx-cursor._fromX)*f;cursor._y=cursor._fromY+(ty-cursor._fromY)*f;cursor.style.transform=`translate(${cursor._x}px,${cursor._y}px)`;if(f<1&&!this.cursorFrame)this.cursorFrame=requestAnimationFrame(()=>{this.cursorFrame=null;this.paintCursors()});cursor.style.setProperty('--peer-color',['#fa8250','#a182ed','#ed6c9b','#23b6c7'][[...id].reduce((a,c)=>a+c.charCodeAt(0),0)%4]);cursor.querySelector('span').textContent=p.name+(glyph==='cursor'?'':' · '+label);
