  showModal(`<div class="modal-header"><div><div class="eyebrow">CREATE TOGETHER</div><h2 id="modalTitle">Share your canvas.</h2><p>Work on the same board, see live cursors, and plan together.</p></div>${closeButton()}</div><form id="joinInviteForm" class="collab-join-panel"><label class="field" for="joinInviteValue"><span>Join by invite link</span><input id="joinInviteValue" type="text" autocomplete="off" spellcheck="false" placeholder="Paste the invite link someone shared with you" required aria-describedby="joinInviteError"></label><div class="collab-join-actions"><button type="button" class="secondary-btn" id="pasteInviteLink">${icon('link')}Paste link</button><button type="submit" class="primary-btn" id="joinInviteButton">Join canvas${icon('arrow')}</button></div><p id="joinInviteError" role="status" aria-live="polite"></p></form><div id="collabDialog"><p>Loading shared canvases…</p></div>`,true);
